import raw from './generated/catalog.json';
import type { Area, AreaId, Catalog, TCode } from '../types.ts';

/** The parsed almanac (393 codes, 18 areas), generated by `npm run data:build`. */
export const catalog = raw as Catalog;

export const CODES: readonly TCode[] = catalog.codes;
export const AREAS: readonly Area[] = catalog.areas;

const byCode = new Map(CODES.map((c) => [c.code, c]));
const byArea = new Map<AreaId, TCode[]>();
for (const c of CODES) {
  const list = byArea.get(c.area) ?? [];
  list.push(c);
  byArea.set(c.area, list);
}

export const getCode = (code: string): TCode | undefined => byCode.get(code);
export const hasCode = (code: string): boolean => byCode.has(code);
export const getArea = (id: AreaId): Area | undefined => AREAS.find((a) => a.id === id);
export const codesInArea = (id: AreaId): readonly TCode[] => byArea.get(id) ?? [];

/** Case-insensitive lookup by exact code. */
export const lookupCode = (input: string): TCode | undefined => byCode.get(input.trim().toUpperCase());
